mapper.select:
SELECT COUNT(profile_id) AS cnt
  FROM LGCOM_PROFILE_M
 WHERE profile_name = #{profileName}

mapper.update:
UPDATE LGCOM_PROFILE_M
   SET profile_name     = #{profileName}
     , profile_desc     = #{profileDesc}
     , use_flag         = #{useFlag}
     , last_updated_by  = #{sessionUserId}
     , last_update_date = SYSDATE
 WHERE profile_id       = #{profileId}

mapper.select:
SELECT COUNT(profile_id) AS cnt
  FROM LGCOM_PROFILE_TARGET_SETUP_N
 WHERE profile_apply_tg_class_code = #{profileApplyTgClassCode}
   AND apply_target_value          = #{applyTargetValue}
   AND profile_id                  = #{profileId}

mapper.update:
UPDATE LGCOM_PROFILE_TARGET_SETUP_N
   SET apply_target_value   = #{applyTargetValue}
     , profile_option_value = #{profileOptionValue}
     , use_flag             = #{useFlag}
     , last_updated_by      = #{sessionUserId}
     , last_update_date     = SYSDATE
 WHERE data_serial_no       = #{dataSerialNo}
